package com.primehr.migration;
import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class OperationsV56MigrationParityTest {@Test void pairedMigrationsHaveMatchingOperationsStructures()throws Exception{String p=read("db/migration/postgresql/V56__operations_reconciliation_retention.sql").toLowerCase();String s=read("db/migration/sqlserver/V56__operations_reconciliation_retention.sql").toLowerCase();for(String m:Set.of(p,s)){assertThat(m).contains("primehr_reconciliation_run","primehr_reconciliation_finding","primehr_retention_policy_version","primehr_legal_hold","fk_reconciliation_finding_run","uk_retention_policy_version","ix_legal_hold_subject");assertThat(m).doesNotContain("delete from","drop table","employeeappointment","payroll_transaction");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
